package documents

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"io"
	"os"

	"filippo.io/age"
)

// KeyDirectory holds private, versioned tenant keys outside the database and
// original storage. Only trusted installation/recovery code calls Provision.
// A missing key is never generated by a read or upload.
type KeyDirectory struct{ disk *Disk }

func OpenKeyDirectory(path string) (*KeyDirectory, error) {
	disk, err := OpenDisk(path)
	if err != nil {
		return nil, err
	}
	return &KeyDirectory{disk: disk}, nil
}
func (k *KeyDirectory) Close() error { return k.disk.Close() }
func keyObject(tenant string) string {
	sum := sha256.Sum256([]byte("document-keys:" + tenant))
	return hex.EncodeToString(sum[:])
}

func (k *KeyDirectory) ring(ctx context.Context, tenant string) (*Keyring, error) {
	if !idPattern.MatchString(tenant) {
		return nil, ErrUnavailable
	}
	file, err := k.disk.Open(ctx, keyObject(tenant))
	if err != nil {
		return nil, ErrUnavailable
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, (1<<20)+1))
	if err != nil {
		return nil, ErrUnavailable
	}
	ring, err := ParseKeyring(data)
	clear(data)
	if err != nil {
		return nil, ErrUnavailable
	}
	if _, err = ring.Current(ctx, tenant); err != nil {
		return nil, ErrUnavailable
	}
	return ring, nil
}

// Provision creates only a previously absent tenant file. Existing invalid or
// unreadable files require recovery; they are never replaced with a new key.
func (k *KeyDirectory) Provision(ctx context.Context, tenant string) error {
	if !idPattern.MatchString(tenant) {
		return ErrInvalid
	}
	if _, err := k.disk.root.Lstat(keyObject(tenant)); err == nil {
		_, err = k.ring(ctx, tenant)
		return err
	} else if !errors.Is(err, os.ErrNotExist) {
		return ErrUnavailable
	}
	data, err := NewKeyFile(tenant)
	if err != nil {
		return err
	}
	defer clear(data)
	err = k.disk.Create(ctx, keyObject(tenant), func(dst io.Writer) error { _, err := dst.Write(data); return err })
	if errors.Is(err, ErrExists) {
		_, err = k.ring(ctx, tenant)
	}
	return err
}
func (k *KeyDirectory) Current(ctx context.Context, tenant string) (string, error) {
	ring, err := k.ring(ctx, tenant)
	if err != nil {
		return "", err
	}
	return ring.Current(ctx, tenant)
}
func (k *KeyDirectory) Recipient(ctx context.Context, tenant, version string) (age.Recipient, error) {
	ring, err := k.ring(ctx, tenant)
	if err != nil {
		return nil, err
	}
	return ring.Recipient(ctx, tenant, version)
}
func (k *KeyDirectory) Identity(ctx context.Context, tenant, version string) (age.Identity, error) {
	ring, err := k.ring(ctx, tenant)
	if err != nil {
		return nil, err
	}
	return ring.Identity(ctx, tenant, version)
}
